<script setup lang="ts">
definePageMeta({ role: 'admin', layout: 'admin' })

type QueueRow = { id: string; queueNumber: string; status: string; doctorId?: string; doctor?: { fullName?: string | null; clinic?: { name?: string | null } | null }; checkIn?: { booking?: { patient?: { fullName?: string | null } | null } | null }; printJobs?: Array<{ id: string }> }
const resetting = ref(false)
const modalOpen = ref(false)
const activeId = ref('')
const saving = ref(false)
const deletingId = ref('')
const forceReset = ref(false)
const errorMessage = ref('')
const successMessage = ref('')
const form = reactive({ status: 'waiting', queueNumber: '' })
const { data, pending, error, refresh } = await useFetch('/api/admin/queues')
const rows = computed(() => (data.value?.data ?? []) as QueueRow[])
const cards = computed(() => { const map = new Map<string, { poli: string; nomor: string; sisa: number; status: string; icon: string }>(); for (const row of rows.value) { const poli = row.doctor?.clinic?.name || 'Tanpa Klinik'; const current = map.get(poli) ?? { poli, nomor: row.queueNumber, sisa: 0, status: 'Aktif', icon: 'i-lucide-stethoscope' }; current.nomor = row.queueNumber; if (row.status === 'waiting') current.sisa += 1; if (row.status !== 'completed') current.status = row.status; map.set(poli, current) } return [...map.values()].slice(0, 6) })
function badgeColor(status: string){ if(status==='completed') return 'success'; if(status==='called') return 'warning'; if(status==='skipped') return 'error'; return 'primary' }
function openEdit(row: QueueRow){ errorMessage.value=''; successMessage.value=''; activeId.value=row.id; Object.assign(form,{ status:row.status, queueNumber:row.queueNumber }); modalOpen.value=true }
async function handleSubmit(){ errorMessage.value=''; successMessage.value=''; if(!activeId.value){ errorMessage.value='Antrean belum dipilih'; return } saving.value=true; try { await $fetch(`/api/admin/queues/${activeId.value}`, { method:'PATCH', body:{ status:form.status, queueNumber:form.queueNumber } }); successMessage.value='Antrean berhasil diperbarui'; modalOpen.value=false; await refresh() } catch (error:any) { errorMessage.value=error?.data?.statusMessage || error?.message || 'Gagal memperbarui antrean' } finally { saving.value=false } }
async function handleDelete(row: QueueRow){ errorMessage.value=''; successMessage.value=''; deletingId.value=row.id; try { await $fetch(`/api/admin/queues/${row.id}`, { method:'DELETE' }); successMessage.value='Antrean dihapus'; await refresh() } catch (error:any) { errorMessage.value=error?.data?.statusMessage || error?.message || 'Gagal menghapus antrean' } finally { deletingId.value='' } }
async function resetQueues(){ resetting.value=true; errorMessage.value=''; successMessage.value=''; try { await $fetch('/api/admin/queues/reset', { method:'POST', body:{ force: forceReset.value } }); successMessage.value='Preview reset berhasil dijalankan' } catch (error:any) { errorMessage.value=error?.data?.statusMessage || error?.message || 'Gagal reset antrean' } finally { resetting.value=false } }
</script>
<template><div class="admin-page"><div class="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><h1 class="text-4xl font-semibold tracking-tight">Manajemen Antrean</h1><p class="mt-2 text-lg text-muted">Pantau dan kelola antrean pasien lintas poli dari backend admin.</p></div><div class="flex flex-col gap-3 sm:flex-row sm:items-center"><label class="flex items-center gap-2 text-sm text-muted"><input v-model="forceReset" type="checkbox" class="size-4" /> force</label><UButton label="Reset Antrean" icon="i-lucide-rotate-ccw" color="warning" :loading="resetting" @click="resetQueues" /><UButton label="Muat Ulang" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="pending" @click="refresh" /></div></div><UPageCard v-if="successMessage" class="admin-table-card border border-success/30"><p class="font-semibold text-success">{{ successMessage }}</p></UPageCard><UPageCard v-if="error || errorMessage" class="admin-table-card border border-error/30"><p class="font-semibold text-error">{{ errorMessage || 'Gagal memuat antrean.' }}</p></UPageCard><div class="grid gap-4 xl:grid-cols-3"><UPageCard v-for="card in cards" :key="card.poli" class="admin-table-card"><div class="space-y-4"><div class="flex items-center justify-between gap-3"><div class="flex size-12 items-center justify-center rounded-2xl bg-primary/10 text-primary"><UIcon :name="card.icon" class="size-6" /></div><UBadge :color="badgeColor(card.status)" variant="subtle">{{ card.status }}</UBadge></div><div><p class="text-sm text-muted">{{ card.poli }}</p><p class="mt-2 text-4xl font-semibold">{{ card.nomor }}</p><p class="mt-2 text-sm text-muted">Sisa antrean {{ card.sisa }}</p></div></div></UPageCard></div><UPageCard class="admin-table-card"><div class="admin-mobile-table overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-elevated/50 text-left text-muted"><tr><th class="px-6 py-4 font-medium">Nomor</th><th class="px-6 py-4 font-medium">Pasien</th><th class="px-6 py-4 font-medium">Dokter</th><th class="px-6 py-4 font-medium">Klinik</th><th class="px-6 py-4 font-medium">Print</th><th class="px-6 py-4 font-medium">Status</th><th class="px-6 py-4 text-right font-medium">Aksi</th></tr></thead><tbody><tr v-if="!pending && rows.length === 0" class="border-t border-default/70"><td colspan="7" class="px-6 py-8 text-center text-muted">Belum ada data antrean.</td></tr><tr v-for="row in rows" :key="row.id" class="border-t border-default/70"><td class="px-6 py-4 font-semibold" data-label="Nomor">{{ row.queueNumber }}</td><td class="px-6 py-4" data-label="Pasien">{{ row.checkIn?.booking?.patient?.fullName || '-' }}</td><td class="px-6 py-4" data-label="Dokter">{{ row.doctor?.fullName || '-' }}</td><td class="px-6 py-4" data-label="Klinik">{{ row.doctor?.clinic?.name || '-' }}</td><td class="px-6 py-4" data-label="Print">{{ row.printJobs?.length || 0 }}</td><td class="px-6 py-4" data-label="Status"><UBadge :color="badgeColor(row.status)" variant="subtle">{{ row.status }}</UBadge></td><td class="px-6 py-4" data-label="Aksi"><div class="flex justify-end gap-2"><UButton icon="i-lucide-pencil" color="neutral" variant="ghost" @click="openEdit(row)" /><UButton icon="i-lucide-trash-2" color="error" variant="ghost" :loading="deletingId === row.id" @click="handleDelete(row)" /></div></td></tr></tbody></table></div></UPageCard><UModal v-model:open="modalOpen" title="Edit Antrean"><template #body><div class="space-y-4"><div v-if="errorMessage" class="rounded-2xl border border-error/30 bg-error/5 px-4 py-3 text-sm text-error">{{ errorMessage }}</div><div class="grid gap-4 md:grid-cols-2"><UFormField label="Nomor antrean"><UInput v-model="form.queueNumber" /></UFormField><UFormField label="Status"><USelectMenu v-model="form.status" :items="['waiting', 'called', 'skipped', 'completed']" /></UFormField></div></div></template><template #footer><div class="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><UButton label="Batal" color="neutral" variant="ghost" @click="modalOpen = false" /><UButton label="Update" icon="i-lucide-save" :loading="saving" @click="handleSubmit" /></div></template></UModal></div></template>
<style scoped>
@media (max-width: 767px) {
  .admin-mobile-table table thead { display:none; }
  .admin-mobile-table table, .admin-mobile-table tbody, .admin-mobile-table tr, .admin-mobile-table td { display:block; width:100%; }
  .admin-mobile-table tr { margin-bottom:1rem; overflow:hidden; border:1px solid rgb(226 232 240); border-radius:1rem; background:white; }
  .admin-mobile-table td { padding:.875rem 1rem; border-bottom:1px solid rgb(241 245 249); }
  .admin-mobile-table td:last-child { border-bottom:none; }
  .admin-mobile-table td::before { content: attr(data-label); display:block; margin-bottom:.35rem; font-size:.7rem; font-weight:700; letter-spacing:.08em; text-transform:uppercase; color:rgb(100 116 139); }
  .admin-mobile-table td .flex.justify-end { justify-content:stretch; flex-wrap:wrap; }
  .admin-mobile-table td .flex.justify-end > * { flex:1 1 0%; }
}
</style>
